from pathlib import Path
import base64,gzip
data=gzip.decompress(base64.b64decode(""""""))
Path("WakeGuard/app/src/main/java/jp/wakeguard/alarm/StreakCompanionView.java").write_bytes(data)
p=Path("WakeGuard/app/build.gradle.kts")
s=p.read_text().replace('versionCode = 150','versionCode = 160',1).replace('versionName = "2.5.0"','versionName = "2.6.0"',1)
p.write_text(s)
assert 'float bodyAt(vec2 uv)' in data.decode()
assert 'DragonFarWing' not in data.decode()
assert 'versionName = "2.6.0"' in p.read_text()
print("Android 2.6.0 realistic dragon renderer installed")